from typing import List

class Solution:
    def evaluate(self, s: str, knowledge: List[List[str]]) -> str:
        d = {k: v for k, v in knowledge}
        result = []
        i = 0
        n = len(s)

        while i < n:
            if s[i] == '(':
                j = i + 1
                while s[j] != ')':
                    j += 1
                key = s[i + 1:j]
                result.append(d.get(key, '?'))
                i = j + 1
            else:
                result.append(s[i])
                i += 1

        return "".join(result)

